import type { SectionItem, SourceCitation } from "@/components/seo/ValueWrapper";

const pdf = { title: "PDF document creation APIs", publisher: "pdf-lib project", url: "https://pdf-lib.js.org/" };
const qpdf = { title: "PDF transformations and encryption", publisher: "QPDF project", url: "https://qpdf.readthedocs.io/en/stable/cli.html" };
const pdfjs = { title: "PDF.js rendering and text extraction", publisher: "Mozilla", url: "https://mozilla.github.io/pdf.js/" };
const irs = { title: "Travel and expense recordkeeping", publisher: "IRS", url: "https://www.irs.gov/publications/p463" };
const uc = { title: "GPA calculation requirements", publisher: "University of California", url: "https://admission.universityofcalifornia.edu/admission-requirements/first-year-requirements/gpa-requirement.html" };
export const toolSources: Record<string, SourceCitation[]> = {
  "pdf/merge": [pdf, qpdf], "pdf/split": [pdf, qpdf], "pdf/from-image": [pdf], "pdf/organize": [pdf], "pdf/page-numbers": [pdf], "pdf/protect": [qpdf], "pdf/unlock": [qpdf], "invoice": [pdf, { title: "1099-NEC reporting instructions", publisher: "IRS", url: "https://www.irs.gov/instructions/i1099mec" }
], "receipt": [irs
], "calc/gpa": [uc
], "calc/final-grade": [{ title: "Weighted arithmetic mean", publisher: "NIST Dataplot", url: "https://www.itl.nist.gov/div898/software/dataplot/refman2/ch2/weigmean.pdf" }], "calc/words-to-pages": [{ title: "Paper formatting guidance", publisher: "APA Style", url: "https://apastyle.apa.org/style-grammar-guidelines/paper-format" }], "pdf/compress": [qpdf, pdfjs], "pdf/to-image": [pdfjs], "pdf/to-text": [pdfjs],
};

export const supplements: Record<string, SectionItem[]> = {
  "pdf/merge": [
    { heading: "Before relying on a combined document", content: `Merge copies of the source files and keep the originals. Check the order using each file's name and page count, then open the generated PDF and verify its first and last pages. A combined output is a new document, not proof that the sources were genuine or complete. PDF editing can invalidate digital signatures, so do not merge signed originals when their signature validation must remain intact.

This merger copies pages rather than promising preservation of every document-level feature. Check bookmarks, interactive fields and accessibility tags if those matter to your workflow. Encrypted files must be unlocked with authorization first; unreadable files are rejected instead of being counted as one page. Unsupported file types are not converted automatically. Device memory limits still apply even though there is no paid quota for the local operation.

For example, combine a two-page cover note and a four-page supporting document in that order. Expect six pages, with the supporting document beginning at page three. Compare that sequence with the downloaded copy before sending it. If the sequence differs, reorder the source list and regenerate. Use an explanatory output file name and retain the unmodified sources so later corrections do not depend on extracting pages from an already edited version.` },
  ],
  "pdf/split": [
    { heading: "Read page positions before entering a range", content: `The range box uses physical PDF page positions starting at one. It does not read the printed page numbers inside a scanned page. A book may begin with a cover and several unnumbered sheets before its printed page one, so first open the source in a reader and identify the positions you need. Note the first and last physical page of the section before entering your selection.

For a ten-page file, entering 1-3, 5 selects physical pages one, two, three and five. Duplicate selections are included once, and output pages are sorted in ascending source order. This splitter is therefore a page-selection tool, not a custom sequencing tool. Use the organizer if you need to move selected pages into another order. Check the final page count as a quick indication that the requested section was extracted correctly.` },
    { heading: "Invalid input should stop extraction", content: `Ranges must contain whole page numbers separated by commas, with ascending endpoints inside the document. Inputs such as 3-1, 2x, 0 or a page beyond the source count are rejected. The parser does not quietly interpret a malformed token as another page. This prevents a typo from producing a plausible but incomplete document.

Correct the entire range and try again after an error. An empty selection is not a request to extract every page. If the document cannot be parsed, no extractable page count is shown; unlock an encrypted source first or obtain a readable copy. Renaming an unrelated file with a PDF extension does not make it a valid PDF. The underlying parser still needs a genuine document structure, not just an acceptable file name.` },
    { heading: "Protect context when extracting evidence", content: `A chapter, contract clause or statement page may refer to information immediately before or after it. Include necessary context and continuation pages when sharing an excerpt. A smaller document is not automatically a complete representation of its source. If a recipient asks for a whole document, splitting it may violate the submission instructions even when every extracted page is readable.

Keep the source separately and give the excerpt a descriptive name. Record the original page positions in your own notes if another person may need to trace the extract. For a bilingual record or translated certificate, verify whether the receiving institution requires both versions together. The splitter cannot make that decision or certify an excerpt. It simply copies your chosen pages into a new file without submitting them to a conversion server.` },
    { heading: "Verify output and understand retained features", content: `Open the downloaded extract rather than relying solely on the success message. Check that its first page is the intended starting point and its final page is the intended ending point. Look for rotated pages, clipped scans and annotations you expected to retain. Some document-wide features, including bookmarks or accessibility structure, may not transfer as expected when pages are copied into a new PDF.

Editing or copying pages can invalidate a source's digital signature. Keep signed originals when signature validity matters. The tool is not a digital-signature validator. Local execution avoids a document upload, but it still uses your device's available memory. If a very large file causes a browser problem, close unrelated tabs and use a suitable desktop application rather than repeatedly retrying the same failing operation.` },
  ],
  "pdf/compress": [
    { heading: "Targets are bounded attempts, not acceptance certificates", content: `Choose a target from the receiving portal's actual requirement. A 200KB preset does not mean USCIS or another agency universally requires 200KB. Use the portal's instructions, permitted formats and document grouping rules. A readable file already below the permitted limit may need no compression at all.

The tool interprets KB as 1,024 bytes. Portals may use different units or rounded displays, so keep a margin. If an adaptive attempt remains above the target, the tool reports that it could not meet the limit rather than offering a falsely successful oversized result. Lossless mode can legitimately return a file above the selected target because it prioritizes retaining page content. File size and document acceptability are separate checks you must perform on the downloaded output.` },
    { heading: "Review what adaptive processing removes", content: `Adaptive compression renders each page and places a JPEG image in a new PDF. That can remove selectable text, links, editable fields, bookmarks and structural accessibility information. A visible signature image is not a preserved cryptographic signature. Keep the original when any of these features matter and use a suitable alternative if the receiving workflow requires them.

Review small numbers, handwritten details and color-dependent marks at a normal reading size. Compare the page count and order. Do not assume a barcode is valid merely because its outline looks sharp. A long color scan may be impossible to fit into a very small target while preserving evidence quality. Re-scan efficiently, use a larger permitted target or split only when the receiving instructions allow it. Repeatedly compressing an already degraded copy rarely restores lost detail.` },
    { heading: "A useful decision example", content: `Suppose your original is 700KB and the actual upload limit is 1MB. Keep the readable original unless you have another reason to reduce it. If the limit really is 500KB, first try structural optimization. If that is insufficient, permit adaptive processing and inspect the resulting images carefully. Stop when important text becomes difficult to read, even if a smaller size is technically possible.

Save the output under a new name so the original remains available. The compression path runs inside the browser and does not submit your file to Cloud OCR. WebAssembly and PDF.js assets may need to download first, so ordinary asset requests do not indicate a document upload. On a shared computer, saved outputs require their own storage and deletion decisions after the browser task has finished.` },
  ],
  "pdf/from-image": [
    { heading: "Use the image formats the exporter can decode", content: `Choose PNG, JPEG or WebP images. A file picker filter helps you find these formats, but it does not repair a corrupted image or change a different format into a supported one. This exporter directly embeds PNG and JPEG; WebP is decoded inside the browser and converted to PNG first. No image is sent to an external format-conversion API.

PNG can preserve transparent pixels, while JPEG is usually a better source for ordinary camera photographs. The tool does not promise to make a low-resolution picture sharp or to recognize text automatically. If you need searchable text, perform a separate OCR workflow and verify the transcript. A PDF containing photographs is still an image document even though its filename now ends with PDF.` },
    { heading: "Prepare a readable sequence before conversion", content: `Inspect every source image for cropping, glare, blur and sideways orientation. Photograph the full relevant page, including corners and marks that support its meaning. Use the up and down controls to order the images; the PDF follows that list. For a receipt batch, decide whether the order should follow date, project or reimbursement item, then confirm the resulting sequence.

The preview shows the uploaded image, not an independent quality certification. If a photo is unreadable, replacing it with a better original is more effective than changing the container format. Keep front and back images together when both contain relevant writing. Avoid adding unrelated photos from the same folder by mistake. Removing a thumbnail removes it from this conversion batch; it does not delete the original file from your device.` },
    { heading: "Page size reflects source image dimensions", content: `Each exported page uses the image's decoded width and height as PDF point dimensions. It does not automatically create a standard Letter or A4 page or infer a calibrated physical size from camera metadata. A large photograph can therefore create a physically large PDF page even when it looks normal in a fit-to-page reader view.

If a recipient requires a specific physical page format, use an appropriate page-layout application or check the PDF printing scale before submission. Do not claim a standardized paper size just because the images have similar aspect ratios. Mixed image sizes can legitimately produce different PDF page dimensions. Review printing with a fit-to-page setting if your immediate goal is a readable paper copy, and keep the digital originals if later layout adjustments may be needed.` },
    { heading: "Consider size and memory when batching photos", content: `A PDF does not inherently compress every embedded photograph to a tiny size. High-resolution camera images may create a large result, and decoding WebP into PNG can increase the embedded data size. Plan the batch according to the receiving portal and your device's memory. Many large images decoded at once can exceed the limits of a phone or browser tab.

Start with a small sample batch if you are unsure. Convert and open the output before adding dozens of files. For a very large collection, smaller logical batches are easier to verify and recover if processing fails. Keep originals until you have reviewed the final PDF. If file size remains too large, the separate compressor offers lossless and adaptive options, with the quality tradeoffs described on that page.` },
    { heading: "A final checklist for a photo-based PDF", content: `Count the source images, confirm their order and compare that count with the number of PDF pages. Check the first and last image and at least one page in the middle. Make sure transparent backgrounds, small handwriting and photo orientation look as intended. Save with a descriptive filename that does not expose unnecessary personal identifiers.

For example, a three-image expense packet might contain the receipt front, receipt reverse and an explanatory note. Expect three pages in that same order. The conversion itself does not authenticate a purchase, create merchant evidence or validate a reimbursement claim. It packages images you supplied. Temporary thumbnail links are released as items are removed or when leaving the tool; files you download remain on your device until you manage them separately.` },
  ],
  "pdf/organize": [
    { heading: "Read the page tiles as a sequence map", content: `The organizer displays numbered page tiles and rotation controls. These tiles identify physical page positions; they are not full rendered previews of the source content. Open the original in a PDF reader when you need to identify exactly what a page contains before deleting or moving it. Printed page numbers inside the document may differ from the tile numbers because of covers and unnumbered sheets.

The output follows the current tile sequence. Moving a tile does not modify the source file in your folder; it changes the new document that will be generated. Work from a copy and retain the original. For a long file, make a simple map of the sections you intend to keep so page-order changes remain deliberate rather than based on a guessed page number.` },
    { heading: "Rotate relative to the document's existing orientation", content: `The rotation control changes a page's existing rotation by the requested quarter-turn. A page already rotated ninety degrees is not treated as a fresh zero-degree page. Additional turns are normalized into the standard full-circle range. This helps you correct sideways scans without accidentally losing the orientation set in the source file.

Rotation changes page presentation; it does not straighten a slightly skewed photograph or crop away scanner margins. If a line slopes by a few degrees, use an image-editing or scanning tool suited to deskewing instead of quarter-turn rotation. Inspect a generated copy in a reader to confirm the result, especially for mixed portrait and landscape documents. Choose the direction that actually makes the content readable rather than assuming all scanned pages need the same adjustment.` },
    { heading: "Delete only pages you can identify safely", content: `A blank-looking scan may still contain faint stamps, pencil notes or a reverse-side mark. Check content in the original reader before deleting it. The organizer retains at least one page so it does not generate an empty document. Deletion applies to the output sequence and does not erase the original source file.

For an evidence packet, preserve required continuation pages, translation pages and attachment context. A shorter file may be easier to navigate but still incomplete for its recipient. If you remove a tile accidentally, reload the original and repeat the intended edits rather than treating the edited sequence as your only source of truth. The tool has no authority to decide which pages an agency, client or reviewer is entitled to receive.` },
    { heading: "Understand the limits of page reconstruction", content: `This tool copies selected pages into a new PDF and sets their rotations. It does not promise to preserve every document-level feature, such as original bookmarks, interactive field relationships, tags or a valid digital signature. A visually similar output may therefore behave differently in a reader. Keep a signed original if its signature or evidentiary status must remain intact.

For accessibility-sensitive work, verify the generated file with appropriate reading and inspection tools. A numbered page sequence is not a substitute for a tagged document structure. Very large sources also depend on local browser memory; there is no remote processing queue to absorb the workload. If your device cannot complete the operation, use smaller permitted batches or a suitable desktop tool instead of repeatedly retrying a crashing browser tab.` },
    { heading: "Test the exact output you intend to share", content: `After generating, download and open the new document. Check the page count, beginning and ending pages, any moved section boundary and each page you rotated. If you intended to remove two pages from an eight-page source, expect six pages. If your intended order is a cover followed by an appendix and then the main text, verify those boundaries rather than relying on a success badge.

Regenerate after any further sequence or rotation change so the download matches the current controls. Give the result a descriptive name and keep the source separately. The operation processes files locally and does not submit document contents to Cloud OCR. Ordinary page and engine loading may still create network requests; saved outputs and any later sharing are separate steps under your control.` },
  ],
  "pdf/page-numbers": [
    { heading: "Distinguish physical pages from displayed counters", content: `The first PDF page is physical position one even when it is an unnumbered cover. The starting-page setting chooses where stamping begins, while the starting-number setting chooses the first displayed counter. They serve different purposes. Skipping a cover does not remove that page from the document, and starting the counter at another value does not reorder any pages.

For example, in a six-page file with a cover, begin stamping at physical page two with counter one. The next five pages receive the sequence one through five. Check whether the receiver expects a plain counter, a counter with dashes or a Page X of Y style. The tool stamps the selected format; it does not inspect an institution's style guide or infer its preferred numbering scheme.` },
    { heading: "Check the space available around page content", content: `Choose a header or footer position and a margin that leaves the new number clear of existing text. A PDF may already contain footnotes, signatures or another page counter near the edge. Stamping does not automatically remove or detect those elements, so two numbers can appear unless you choose an appropriate location.

Use a modest font size and inspect the generated file. If a source has pages of different dimensions, the number's position is calculated for each page rather than assumed from a single paper size. Very small pages may not have enough room for your chosen label. Increase or decrease the margin with care: a larger margin moves the stamp farther into the page content, while a smaller one can put it near the printable edge.` },
    { heading: "Treat this as pagination, not a full legal Bates system", content: `Simple page counters help readers refer to a document consistently. A full legal production system may require prefixes, fixed-width identifiers, confidentiality legends, document IDs and an audit trail that this tool does not implement. Do not call a plain counter a certified Bates production just because the page title mentions numbering.

If a lawyer, court or organization provides a required format, compare it with the actual options before using the output. Retain the unmodified source and any official production record separately. The generator adds visual text to a new PDF; it does not establish document authenticity or replace a chain-of-custody process. Choose a different system when you need capabilities beyond the displayed numbering choices.` },
    { heading: "Signed, protected and rotated source documents", content: `Unlock an encrypted PDF using a password you are authorized to use before adding page numbers. The tool does not bypass encryption by ignoring it. Editing a digitally signed file can invalidate signature verification; preserve the original if that validity matters. A visible signature mark in the edited copy is not evidence that the cryptographic signature remains valid.

Mixed rotations require particular care because a PDF's coordinate system and its displayed orientation can differ. Open the output at its ordinary viewing rotation and confirm that the label is readable and located where you intended. If a document needs a more specialized stamp transformation, use appropriate PDF editing software. Page numbering is a document modification, so always compare the output rather than treating generation success as proof that every page layout is correct.` },
    { heading: "Verify a representative sample and retain the source", content: `Review the first stamped page, the final page and one page in the middle. If you skipped a cover, confirm that the cover remains unnumbered. Check the displayed sequence against your starting counter and make sure the label does not cover relevant text. A one-page source is a useful trial for unfamiliar settings, while mixed page sizes should be tested on more than one page.

Regenerate after changing position, font size, margin or starting values. The previous download should not be treated as the new result. Save the numbered file under another name so it cannot overwrite your only unmodified copy. Processing happens in browser memory, without sending document bytes to a stamping service. Downloaded documents remain ordinary local files and need storage decisions appropriate to their contents.` },
  ],
  "pdf/protect": [
    { heading: "Choose a password you can retain safely", content: `Encryption protects a document only as well as the password and the surrounding workflow. Use a strong, unique password and store it in a password manager or another approved location. Confirm it carefully before generating the encrypted file. This site does not keep a recovery copy of your password and cannot restore access if you lose it.

Keep the unencrypted original in a secure location until you have tested the encrypted output. Do not share the password in the same message as the file when your organization's policy calls for separate delivery. Check the intended recipient's PDF reader for AES-256 support before relying on the document as the only usable copy. Encryption changes access to the file; it does not establish the recipient's identity or decide whether you should disclose the information.` },
    { heading: "Permissions are distinct from the opening password", content: `The opening password controls whether an ordinary reader can decrypt the document. Printing and copying permissions describe restrictions for readers that honor the PDF permission flags. They are not an absolute technical guarantee that visible information cannot be captured, photographed or reproduced. Someone authorized to see a document may still have other ways to record it.

The tool uses a separate random owner password when setting the displayed restrictions, so the ordinary opening password does not automatically act as the owner credential. Keep your unmodified source for future editing. Do not depend on disabled-copy or disabled-print options as a substitute for access controls, recipient agreements or secure handling. Review the encrypted file in the reader your recipient uses, because software can differ in how it interprets permissions.` },
    { heading: "What AES-256 verification covers", content: `The encryption path uses QPDF in WebAssembly with a 256-bit key setting. After generation, the tool inspects the result to check that encryption is present. This is a software verification of the produced PDF, not an independent security audit of every browser, extension or endpoint involved. A successfully encrypted file can still be exposed if its password is weak or sent to the wrong person.

Try opening the downloaded result in a fresh reader session. Confirm that it asks for the password and that the correct password displays every page. A wrong password should fail. Check visible content and page count against the original. These practical checks help catch an unusable output or a file mix-up before you discard the source, and they test the copy you actually intend to distribute.` },
    { heading: "Avoid inappropriate security promises", content: `Password-protecting a PDF does not certify HIPAA, GDPR, contractual or institutional compliance. Those obligations can include device security, sharing policy, retention, approval and recipient access. Use your organization's guidance when handling regulated or confidential records. The tool supplies an encryption operation, not a legal determination.

Some application portals explicitly reject password-protected files. Check the receiving instructions before adding encryption to a submission. If the recipient cannot open the file, encryption has not improved that workflow. When a portal requires an unencrypted document, use an approved transmission channel instead of assuming this password tool can override the portal's rules. Preserve both confidentiality and practical accessibility according to the real task you need to complete.` },
    { heading: "Local operation and recovery boundaries", content: `The selected PDF and entered password are processed locally by the browser's document engine. This tool does not send the password to the contact API or Cloud OCR. Engine assets may load when needed, so complete the first initialization before expecting offline operation. The browser's memory lifecycle is not a guaranteed secure-erasure process.

Save the output with a clear filename and test it before sharing. A failed generation should not be interpreted as permission to bypass encryption or silently ignore a damaged source. Obtain a readable original instead. If a page, font or reader behaves unexpectedly, describe the problem to support using a synthetic example and the browser version, without sending the real password or confidential document. Retain your source until the encrypted copy is verified and backed up appropriately.` },
  ],
  "pdf/unlock": [
    { heading: "Use this tool only for authorized access", content: `Unlocking removes encryption using a valid document password. It is not a password-cracking service and does not discover a forgotten password. You need the opening or owner password and authorization to produce an unencrypted copy. If you do not have that permission, ask the document's owner or issuing organization for a suitable copy rather than trying to bypass access controls.

For a protected statement you already have permission to use, first confirm its source and password. If the file is not encrypted, there is no unlocking operation to perform; use the original document. A PDF may look restricted in a reader without requiring a password to open, but the tool still follows its encryption checks rather than promising to remove every kind of reader limitation.` },
    { heading: "Understand the difference between wrong passwords and damaged files", content: `A wrong-password error means the supplied credential was not accepted. Check capitalization, pasted spaces and the password supplied by the issuer. Do not repeatedly guess private credentials. A parse or processing failure may instead indicate a damaged or unsupported PDF, so changing the password will not necessarily help.

Download a fresh original from the authorized source if you suspect corruption. Changing a filename or extension does not repair the internal structure. Keep the protected source until the output is tested. The tool checks whether the result remains encrypted before marking the operation successful; if that check fails, it reports the problem rather than calling the file unlocked. A successful verification concerns this operation, not every possible feature or signature in the source.` },
    { heading: "An unlocked copy has a different confidentiality boundary", content: `Anyone who can access an unencrypted output file may be able to read its contents without the original password. Decide where you will save it before generating it. A convenient download folder may be shared, backed up or synchronized to another service. Removing encryption can therefore change the practical exposure of the document even though the unlocking computation stayed local.

Use an appropriate private folder and follow your organization's policy. If your aim is to upload to a portal that forbids encrypted documents, confirm the portal's actual requirement and use its approved submission channel. Do not remove protection from a file simply because another online tutorial says all PDFs should be unlocked. The need for an unencrypted copy depends on the task and the permission you were given.` },
    { heading: "Review the unencrypted document before further editing", content: `Open the downloaded copy in a fresh reader session and confirm that it displays without asking for the password. Compare the page count and first and last pages with the original. Check annotations, fields and other important features before running another transformation such as compression or extraction.

Changing encryption can affect how a reader presents a document and may invalidate a source digital signature. Keep the signed original when validation matters. Do not claim that a visible signature in an edited copy is still cryptographically valid without using a proper signature validator. If your purpose is merely to read the protected original, you may not need to create another copy at all; opening it with the authorized password in your usual reader may be sufficient.` },
    { heading: "No recovery service and no password retention promise", content: `The site does not maintain your document password or an account vault. Unlocking is performed in browser memory using QPDF WebAssembly. Website or engine downloads may occur, but document bytes and passwords are not sent to the optional cloud transcription endpoint by this tool. Closing a tab does not securely erase every possible system memory copy or delete the output you saved.

If you report a problem, do not include the real password or sensitive document contents. A synthetic protected PDF and reproducible steps are better evidence for software debugging. For example, test a two-page sample with a password you created, then confirm a wrong password fails and the correct one succeeds. This distinguishes an application problem from an inaccessible source without exposing the information you were trying to protect.` },
  ],
  "pdf/to-image": [
    { heading: "Choose resolution with device memory in mind", content: `Rendering at 300 DPI creates four times as many pixels as rendering the same page at 150 DPI. That can improve small-text detail, but it also increases canvas memory and export size. Try 150 DPI for an ordinary preview and 300 DPI when the destination needs more detail. A low-quality source photograph does not acquire new detail simply because you select a higher rendering DPI.

Image export supports up to fifty pages per batch. Larger documents must be split first; the tool should not silently omit later pages and call the result complete. Oversized physical pages can also produce large canvases even in a short file. Check the output dimensions and consider a lower DPI when a browser or phone cannot safely allocate the rendered image.` },
    { heading: "Select PNG or JPEG deliberately", content: `PNG preserves sharp lines without JPEG-style compression artifacts and can retain transparent areas. JPEG uses a white background in this tool and is often more compact for photographs. The best choice depends on the source and what the recipient needs, not a blanket claim that one format is always superior.

Changing the selected format or DPI clears an existing generated batch. Generate a fresh batch before downloading so filenames and image contents agree. The displayed pixel dimensions describe raster output; they do not guarantee that another application will interpret an embedded physical-resolution label. If you need a print workflow with explicit size or DPI metadata, check the image in that destination application rather than relying solely on the preset label.` },
    { heading: "Inspect the batch and ZIP contents", content: `Compare the number of generated images with the PDF's page count. Open at least the first image, last image and a page with small text or a photograph. Image conversion removes the PDF's selectable text, links, fields and signatures as interactive document features. The images represent rendered appearance, not a reusable digital text layer.

Use individual downloads for a small selection or the ZIP bundle for the complete generated batch. Extract the ZIP and inspect the files before sharing it. Some portals do not accept ZIP archives, so upload the required individual file format instead. Keep the original PDF and avoid renaming a JPEG file as PNG; changing an extension does not convert image data. This tool exports locally and does not upload pages to a rendering server.` },
  ],
  "pdf/to-text": [
    { heading: "Read native text and scanned pages in their original order", content: `The local pipeline inspects each page for extractable text. Pages with native text use PDF.js; pages without text are rendered for Tesseract OCR. The output follows the PDF's original page order. A short digital line is still useful text and should not be discarded merely because it has fewer than an arbitrary number of characters.

Mixed documents need particular review. A page can contain digital text plus an image with additional writing; a native-text pass does not necessarily recognize the writing inside that image. The tool's result is therefore a transcript to check, not a guaranteed complete reconstruction of every visual element. Compare names, amounts, dates and table columns with the original before relying on the output for another task.` },
    { heading: "Understand local engine downloads and cloud limits", content: `On first use, the local OCR engine may download its worker, WebAssembly resources and English language data. These requests do not contain your selected document, but they mean that opening the page alone is not a guarantee of immediate offline OCR. Processing can take longer for scanned pages than native text. Keep the tab open and allow the sequential page work to finish.

Optional Cloud OCR is disabled by default pending provider and deployment review. When enabled, it requires explicit consent, supports files up to four MB and twenty PDF pages, and has request quotas. Its output may be incorrect or incomplete. Google provider terms govern external data use; this site does not promise zero retention. Use local extraction when you need to avoid sending file contents, and use a suitable dedicated OCR application if the available model or language support is insufficient.` },
    { heading: "Editing and searching are separate actions", content: `Search filters the displayed transcript to matching lines. While that filter is active, the text area is read-only so an edit cannot accidentally replace the full transcript with only the visible matches. Clear the search before editing the complete text. Copy and download actions use the full current transcript rather than treating a filtered view as the only result.

Clipboard access depends on browser permissions and a suitable page context. If copying is blocked, select the text manually or use the text download. OCR errors are reported separately from successful extracted content so a service failure is not mistaken for a document's words. Retain the original file alongside a verified transcript. Plain text does not preserve page geometry, signatures or every table relationship, even when its words appear correct.` },
  ],
  "invoice": [
    { heading: "Verify the invoice as a business record", content: `Enter actual sender and client names, valid dates, complete line descriptions and agreed amounts. The export rounds monetary lines, wraps long fields and adds pages when needed. It reports unsupported font characters rather than silently deleting them. Open the generated PDF before sending it and inspect payment instructions, references, currency and total.

An invoice request does not prove payment or create new agreed terms by itself. Confirm tax treatment and fees using your own agreement and applicable requirements. The tool's calculation order applies a percentage discount before its invoice-wide tax rate; this is a software model, not jurisdiction-specific tax advice. A change to any input clears the old download so an earlier amount is not presented as the current result.

Keep issued invoices, delivery evidence and payment records linked in your own ledger. U.S. information reporting thresholds do not establish a tax-free income allowance. Consult current IRS instructions and a qualified accountant when deciding reporting obligations. The generator processes entries locally, but emailing the resulting invoice is a separate disclosure you control. Do not include unnecessary personal identifiers or sample bank details in a document you send to a client.` },

{"heading":"Check the arithmetic with a small example","content":"Consider an item for two hours at USD 50.00 and a second item for USD 25.00. The subtotal is USD 125.00. Under the tool’s model, a ten percent discount reduces the taxable base to USD 112.50; a ten percent tax then produces USD 11.25, giving a total of USD 123.75. This describes the calculator’s displayed arithmetic, not a determination that every item is taxable or that discount treatment is the same in every jurisdiction.\n\nEach line and total is rounded to currency cents. Compare the exported amount with the preview and with your accounting record. For credits, exempt items, mixed tax rates, foreign exchange or jurisdictions requiring another decimal precision, use a billing system that supports those rules. Do not force an unsuitable transaction into a single percentage field. The export uses currency codes to make the denomination explicit.\n\nA useful review sequence is to confirm the customer, invoice reference, dates, item descriptions, quantities, unit prices, discount, tax and payment instructions before generating. Open the downloaded PDF and verify the last line and final notes as well as the first page. Long descriptions flow across pages instead of being cut off. Keep a final copy and a record of any correction; changing the browser form does not rewrite a PDF already sent to a client."},
],
  "receipt": [
    { heading: "Use actual facts rather than an invented merchant record", content: `This tool produces a self-entered expense log, not a merchant receipt or proof that a transaction occurred. Category selection only changes the category; it does not invent vendor names, card numbers or purchases. Enter the actual payee, date, location, business purpose and amounts from your records. Evidence status starts unspecified, so the tool does not claim an original receipt exists unless you choose that status.

Retain original receipts and other supporting evidence when required. A generated voucher cannot by itself establish deductibility or replace every documentary requirement. Review the downloaded copy and confirm its explicit self-entered disclaimer. Long fields and item lists wrap onto additional pages so the log preserves what you entered. For another writing system, use software with suitable fonts if this exporter reports unsupported characters. The USD total is a calculation, not a currency-conversion or tax determination.` },

{"heading":"An expense log accompanies genuine supporting evidence","content":"This generator produces your personal record of an expense. It does not create an original merchant receipt, authenticate a transaction, or establish that a deduction is allowed. Use it alongside genuine receipts, payment confirmations and business-purpose records. If evidence is missing, describe the gap honestly rather than marking a receipt attached merely to make the form look complete.\n\nIRS Publication 463 describes supporting records for particular travel, gift and related expense rules. Its documentary-evidence exceptions are contextual, including lodging and circumstances where evidence is not readily available. They should not be treated as permission to invent evidence or as a universal rule for every business expense. A credit-card payment record may show an amount and vendor while omitting the itemized business purpose. Keep the supporting details that apply to the expense and ask a qualified adviser when the classification is uncertain.\n\nFor example, an expense packet for a business trip may include the hotel’s itemized bill, a genuine transport receipt and a short note identifying the work meeting. Enter separate descriptive items instead of a vague “travel” total. Check the date, location, currency and actual amounts against those documents. Include only expenses that really occurred. Meals, travel, supplies and lodging can have different substantiation and deduction rules; a category button does not decide their tax treatment.\n\nBefore exporting, verify whether taxes and tips are already included in a listed item so they are not counted twice. The generator adds the separate fees and tip fields to the entered items. Save the PDF with a useful reference, then keep it with the actual evidence under your own retention policy. The tool does not submit a reimbursement request, calculate a deductible percentage, keep a server archive or guarantee audit acceptance. Update a mistaken record transparently and retain context for the correction rather than presenting it as an unchanged original."},
],
  "calc/gpa": [
    { heading: "Use credits and actual course grades, not a single summary GPA", content: `The weighted summary alone does not identify which courses received bonuses, so an exact unweighted result cannot be recovered by subtracting a fixed number. Enter each grade, level and credit value. The calculator weights the quality points by credits rather than treating a half-credit course as a full-credit course. Zero-credit entries are excluded; invalid or absent credits do not silently become one credit.

This example policy awards a half-point Honors bonus or one AP/IB point for passing grades. Failing grades receive no bonus. Your school may use another policy, so compare its transcript instructions with these assumptions. When no included credits remain, the zero display means no calculable average, not an official academic record. Use the displayed plus/minus values consistently and avoid entering both semester and annual grades unless your school's method counts both.` },
    { heading: "Avoid fictional admissions cutoffs", content: `The results do not predict admission or establish a qualifying score for ranked universities. A college's minimum eligibility requirement, admitted-student range and enrolled-student average are different statistics, and they may use different GPA scales. Check the current institution's official instructions before making a comparison.

This is not a UC capped GPA calculator. UC uses its own eligible course period, course definitions and honors-point cap. Use the linked UC instructions and your school counselor for that calculation. If an application asks for the GPA and scale shown on your transcript, report those values instead of replacing them with this estimate. For example, two equal-credit A courses, one regular and one AP, produce 4.0 unweighted and 4.5 weighted under this tool's model; that illustration is arithmetic, not a promise of college eligibility. Keep your course list for review and use the estimate for planning.` },
    { heading: "Review changes one course at a time", content: `Check the total credits against the transcript list, then manually calculate a small two-course sample to confirm the mapping. A unexpectedly large change usually warrants checking the course credit value or level. Course names help you identify rows but are not required personal identifiers; do not enter a student ID when it adds nothing to the calculation.

The browser calculates locally. A screenshot you later share is a separate disclosure, and the calculator does not certify school records. Consult your counselor when repeat courses, pass/fail grades or transfer rules make the transcript more complex than this model.` },

{"heading":"Work through credits rather than guessing a conversion","content":"Suppose one eligible course earns an A for one credit and another earns a B for two credits. Under this scale, the quality points are four times one plus three times two, totaling ten. Divide by three total credits to obtain an unweighted GPA of about 3.33. Giving both courses equal influence would produce a different result and would ignore the credit information.\n\nNow consider whether either course qualifies for a difficulty bonus under the rules you actually need. This calculator’s optional weights are illustrative. A zero-credit course is excluded from the denominator; it is not silently treated as one credit. A failed advanced course earns zero under the displayed model rather than receiving a positive difficulty bonus. Do not enter empty, negative or guessed credits just to make an overall number match a desired result.\n\nWhen a result differs from the transcript, compare each course, grading period, credit value and plus/minus mapping first. Schools may count repeats, pass/fail work or nonacademic courses differently. Resolve those policy differences before using the estimate on an application. Keep the original transcript authoritative and follow the receiving institution’s instructions for self-reported grades."},
],
  "calc/final-grade": [
    { heading: "Check the assumptions before interpreting the required score", content: `The current grade must represent the completed portion of the course, excluding the final exam. The final weight must match the syllabus and be greater than zero. If your gradebook already includes a zero for an unsubmitted final, its displayed average may not be the right current-grade input. Ask the instructor or reconstruct the completed-work average first.

The curve setting models an assumed addition to the overall target calculation; it does not promise that your instructor will award extra credit. A required score above one hundred indicates that the stated target is impossible under the standard exam model without another grading rule. A nonpositive requirement indicates that a zero final score still meets the chosen target in the arithmetic model. Neither outcome tells you whether attendance, minimum exam scores or other syllabus conditions also apply.` },
    { heading: "A worked example you can reproduce", content: `If your current grade is eighty percent, the final contributes twenty percent and you want eighty-four percent overall, completed work contributes sixty-four percentage points. The exam must contribute twenty more points, requiring a hundred percent exam score. Enter those values and confirm the displayed result. If the final instead contributes forty percent, recalculate with that actual weight rather than assuming the required score stays the same.

Use the result to decide which assumptions to discuss with the instructor and which material needs review. The gauge is a visual description of the numerical requirement, not a validated prediction of study hours or academic success. Save your own notes about the syllabus, input values and relevant grading rules so another person can check the calculation. This tool has no connection to your institution's gradebook and cannot update an official course grade.` },
    { heading: "Handle boundaries honestly", content: `Enter finite grades and a final weight from greater than zero through one hundred percent. A zero-weight final cannot change an overall grade and therefore has no meaningful required-exam calculation. Invalid inputs should produce an explanation rather than quietly substituting a different exam weight. Extra-credit grading systems can legitimately exceed one hundred, but their rules should be modeled separately if they differ from this weighted-average calculation.

The tool runs locally and does not need your student name or ID. Its output is an estimate based on entered assumptions. Use a counselor or instructor for course-specific grading and planning questions, particularly when missed-work rules or multiple remaining assessments change what the current grade means.` },
  ],
  "calc/words-to-pages": [
    { heading: "Page counts are estimates, not exact typesetting", content: `Words occupy different widths, and a document's headings, tables, paragraphs and page breaks use space beyond ordinary prose. A words-per-page constant is useful for planning but cannot reproduce a word processor's final layout. Check the actual document in the required font, spacing, margins and paper size before submitting work with a strict page limit.

The tool uses stated constants for a Letter-sized page with one-inch margins and twelve-point text. An APA or MLA reference does not certify that every document produced elsewhere will match those constants. Large quotations, figures or bibliography entries can significantly change the result. Compare an ordinary page of your own draft with the estimate to understand how much room the final layout may need.` },
    { heading: "Manual counts and pasted text have different roles", content: `Paste a draft to calculate a whitespace-based word count and character counts, or enter a manual count when you already know the number of words. The manual input overrides the page and speech estimate, while the pasted-text character metrics still describe the actual text area. Clear the override if you want the estimates to follow your edited draft again.

Punctuation, hyphenation and language-specific segmentation can make this simple count differ from a word processor's count. Use the required application's result when an assignment specifies a counting method. Empty or negative manual input should not produce negative pages or speaking time. The calculator is a convenient planning tool; it does not inspect an uploaded manuscript or validate a submission limit.` },
    { heading: "Rehearsal is the best check on a speech estimate", content: `The speech display uses sample rates of 110, 130 and 150 words per minute. These estimates exclude pauses, audience questions, slide changes and pronunciation difficulties. Rehearse aloud with a timer, then revise the draft to fit your actual delivery. Speaking faster to force a long script into a short slot may make it harder to follow.

For example, a 650-word script at 130 words per minute takes five minutes before additional pauses. Add room for transitions and important explanations. The displayed seconds are normalized so rounding does not produce a sixty-second remainder. Pasted text remains in the browser, and no account or transcript upload is needed. If the draft contains confidential information, remember that screenshots, clipboard use and downloads are separate actions controlled by you.` },
  ],
};
